public class Solution {
    static String caesar(String text, int shift) {
        StringBuilder sb = new StringBuilder();
        int k = Math.floorMod(shift, 26);
        for (char c : text.toCharArray()) {
            if (c >= 'a' && c <= 'z') sb.append((char) ('a' + (c - 'a' + k) % 26));
            else if (c >= 'A' && c <= 'Z') sb.append((char) ('A' + (c - 'A' + k) % 26));
            else sb.append(c);
        }
        return sb.toString();
    }

    static boolean isAnagram(String a, String b) {
        int[] counts = new int[26];
        for (char c : a.toLowerCase().toCharArray()) if (c >= 'a' && c <= 'z') counts[c - 'a']++;
        for (char c : b.toLowerCase().toCharArray()) if (c >= 'a' && c <= 'z') counts[c - 'a']--;
        for (int n : counts) if (n != 0) return false;
        return true;
    }

    static String compress(String s) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            int run = 1;
            while (i + run < s.length() && s.charAt(i + run) == c) run++;
            sb.append(c);
            if (run > 1) sb.append(run);
            i += run;
        }
        return sb.length() < s.length() ? sb.toString() : s;
    }

    static String capitalizeWords(String s) {
        StringBuilder sb = new StringBuilder();
        for (String w : s.trim().split("\\s+")) {
            if (w.isEmpty()) continue;
            if (sb.length() > 0) sb.append(' ');
            sb.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1).toLowerCase());
        }
        return sb.toString();
    }
}

unitTests:
test("Caesar cipher", () -> {
    checkEq(Solution.caesar("Hello, World!", 3), "Khoor, Zruog!");
    checkEq(Solution.caesar("Khoor, Zruog!", -3), "Hello, World!");
    checkEq(Solution.caesar("xyz ABC", 29), "abc DEF");
    checkEq(Solution.caesar("", 5), "");
});

test("anagrams", () -> {
    checkEq(Solution.isAnagram("Listen", "Silent"), true);
    checkEq(Solution.isAnagram("Dormitory", "dirty room!"), true);
    checkEq(Solution.isAnagram("abc", "abd"), false);
    checkEq(Solution.isAnagram("aab", "ab"), false);
});

test("compression", () -> {
    checkEq(Solution.compress("aaabccdddd"), "a3bc2d4");
    checkEq(Solution.compress("abc"), "abc");
    checkEq(Solution.compress("aabb"), "aabb");
    checkEq(Solution.compress("zzzzzzzzzzzz"), "z12");
    checkEq(Solution.compress(""), "");
});

test("capitalizing", () -> {
    checkEq(Solution.capitalizeWords("the QUICK brown"), "The Quick Brown");
    checkEq(Solution.capitalizeWords("  hello   world "), "Hello World");
    checkEq(Solution.capitalizeWords(""), "");
});

